contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address newOwner, uint256 sendAmount) public payable {
        require(address(this).balance >= sendAmount);
        // record balance of c before the call
        uint256 balBefore = address(c).balance;

        // attempt call and record whether it reverted
        bool reverted;
        bool ret;
        try c.setOwner{value: sendAmount}(newOwner) returns (bool success) {
            reverted = false;
            ret = success;
        } catch {
            reverted = true;
            ret = false;
        }

        uint256 balAfter = address(c).balance;

        // General rule: setOwner does not change C's ether balance regardless of inputs or revert
        assert(balAfter == balBefore);
    }
    receive() external payable {}
}
